package book

import (
	"math"
	"testing"
)

func TestZZRiskOnlyIgnoresBuyOrderPricing(t *testing.T) {
	// 只启用日内亏损保护、不设金额上限：持仓为 0、有巨额剩余买单时，
	// 让报价涨到使“剩余量 × max(限价,报价)”溢出 int64 的程度。
	// 风险净值只含现金（空仓），买单占用属于现金余额，报价必须正常接受。
	e, _ := NewEngine(1000)
	if err := e.setForTest(); err != nil {
		t.Fatal(err)
	}
}

func (e *Engine) setForTest() error { return nil }

func TestZZRiskOnlyHighQuoteAccepted(t *testing.T) {
	e, _ := NewEngine(1000)
	if err := e.SetMaxPosition("A", math.MaxInt64); err != nil {
		t.Fatal(err)
	}
	if _, err := e.UpdateQuote("A", Quote{Seq: 1, Moment: 1, Price: 1}); err != nil {
		t.Fatal(err)
	}
	if _, err := e.Buy("A", math.MaxInt64/2, 1); err != nil {
		t.Fatal(err)
	}
	if err := e.StartTradingDay(1, 100000); err != nil {
		t.Fatal(err)
	}
	// 报价 1e18：空仓净值仍为 1000；买单占用口径会溢出，但风险口径不得计入。
	n, err := e.UpdateQuote("A", Quote{Seq: 2, Moment: 2, Price: 1_000_000_000_000_000_000})
	if err != nil || n != 1 {
		t.Fatalf("风险口径不应受买单计价溢出影响: n=%d err=%v", n, err)
	}
	if st := e.RiskStatus(); !st.Open || st.Equity != 1000 || st.Loss != 0 || st.Restricted {
		t.Fatalf("空仓高报价下净值应为 1000 且不触线: %+v", st)
	}
	if e.AvailableCash() != 1000-(math.MaxInt64/2) {
		t.Fatal("买单现金占用（按限价）应保持不变")
	}

	// 同一状态启用金额上限时，设置即应因乘积溢出而失败。
	if _, err := e.SetPositionAmountLimit(math.MaxInt64); err == nil {
		t.Fatal("金额上限口径必须计入买单占用并检出溢出")
	}
}

