	n, err := e.UpdateQuote("A", Quote{Seq: 2, Moment: 2, Price: 1_000_000_000_000_000_000})
	if err != nil || n != 1 {
		t.Fatalf("风险口径不应受买单计价溢出影响: n=%d err=%v", n, err)
	}
	if st := e.RiskStatus(); !st.Open || st.Equity != 1000 || st.Loss != 0 || st.Restricted {
